<?php
declare(strict_types=1);namespace Pam\Native\LiveActivities;use InvalidArgumentException;final readonly class LiveActivityContent{public function __construct(public string$title,public string$status='',public float$progress=0,public string$deepLink=''){if($title===''||strlen($title)>128||strlen($status)>256||!is_finite($progress))throw new InvalidArgumentException('Invalid live activity content.');if($deepLink!==''&&(!preg_match('/^[a-z][a-z0-9+.-]*:\/\//iD',$deepLink)||strlen($deepLink)>2048))throw new InvalidArgumentException('Invalid live activity deep link.');}public function payload():array{return['title'=>$this->title,'status'=>$this->status,'progress'=>max(0,min(1,$this->progress)),'deepLink'=>$this->deepLink];}}
